import React from "react";
import { useNavigate } from "react-router-dom";
import "../styles/Navbar.css";

const Navbar = () => {
  const navigate = useNavigate();

  const handleLogout = () => {
    localStorage.removeItem("user");
    navigate("/login");
  };

  return (
    <nav className="navbar">
      <div className="navbar-content">
        <h1 className="navbar-title" onClick={() => navigate("/user-home")}>
          CADENCE 🎵
        </h1>
        <div className="navbar-links">
          <button onClick={() => navigate("/user-home")}>Home</button>
          <button onClick={() => navigate("/profile")}>Profile</button>
          <button onClick={() => navigate("/gigs")}>Gig Board</button>
          <button onClick={() => navigate("/chat")}>Chat</button>
          <button onClick={handleLogout} style={{ backgroundColor: "#ff6600", color: "#fff" }}>
            Logout
          </button>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
